import React, { useState, useContext, useMemo } from 'react';
import { Link } from 'react-router-dom';
import Icon from 'components/AppIcon';
import { ProgressContext } from '../../contexts/ProgressContext';
import { DataContext } from '../../contexts/DataContext';
import { AIContext } from '../../contexts/AIContext';

import LearningMetricsOverview from './components/LearningMetricsOverview';
import KnowledgeNetworkMap from './components/KnowledgeNetworkMap';
import PerformanceTrendChart from './components/PerformanceTrendChart';
import AchievementGallery from './components/AchievementGallery';
import AIInsightsPanel from './components/AIInsightsPanel';
import AccessibilityAnalytics from './components/AccessibilityAnalytics';
import PeerComparisonCard from './components/PeerComparisonCard';
import ExportProgressModal from './components/ExportProgressModal';

const ProgressAnalyticsDashboard = () => {
  const [selectedTimeRange, setSelectedTimeRange] = useState('7d');
  const [selectedSubject, setSelectedSubject] = useState('all');
  const [showExportModal, setShowExportModal] = useState(false);

  const { learningNodes = [], loading: progressLoading } = useContext(ProgressContext) || {};
  const { userStats, achievements = [], analytics, loading: dataLoading } = useContext(DataContext) || {};
  const { getLearningRecommendations } = useContext(AIContext) || {};

  const isLoading = progressLoading || dataLoading;

  const analyticsData = useMemo(() => {
    const completedNodes = learningNodes.filter((n) => n.progress >= 100);
    const overallProgress = learningNodes.length
      ? Math.round(learningNodes.reduce((sum, n) => sum + (n.progress || 0), 0) / learningNodes.length)
      : 0;

    const subjectsMap = {};
    learningNodes.forEach((node) => {
      if (!subjectsMap[node.subject]) {
        subjectsMap[node.subject] = { progress: 0, hours: 0, concepts: 0, count: 0 };
      }
      subjectsMap[node.subject].progress += node.progress || 0;
      subjectsMap[node.subject].hours += node.timeSpent || 0;
      subjectsMap[node.subject].concepts += node.progress >= 100 ? 1 : 0;
      subjectsMap[node.subject].count += 1;
    });

    const colorMap = {
      mathematics: 'primary',
      programming: 'accent',
      history: 'secondary',
      science: 'success',
    };

    const subjects = Object.entries(subjectsMap).map(([name, data]) => ({
      name: name.charAt(0).toUpperCase() + name.slice(1),
      progress: data.count ? Math.round(data.progress / data.count) : 0,
      hours: Math.round(data.hours * 10) / 10,
      concepts: data.concepts,
      color: colorMap[name] || 'primary',
    }));

    const weeklyActivity = (analytics?.weeklyProgress || []).map((entry) => ({
      day: entry.day,
      hours: entry.hours || 0,
      concepts: entry.completed || 0,
    }));

    const recommendations = getLearningRecommendations?.() || [];

    return {
      overallProgress,
      learningStreak: userStats?.streak || 0,
      totalHours: userStats?.totalHours || 0,
      conceptsMastered: completedNodes.length,
      subjects,
      weeklyActivity,
      achievements: achievements.map((a) => ({
        id: a.id,
        title: a.title,
        description: a.description,
        icon: a.icon || 'Award',
        earned: true,
        date: a.earnedAt || a.unlockedAt,
      })),
      aiInsights: recommendations.map((rec) => ({
        type: rec.type,
        title: rec.title,
        content: rec.suggestion || rec.reason || '',
        action: rec.topics ? `Review: ${rec.topics.join(', ')}` : rec.title,
        priority: rec.priority || 'medium',
      })),
      peerComparison: {
        averageProgress: overallProgress,
        averageHours: userStats?.totalHours || 0,
        averageStreak: userStats?.streak || 0,
        ranking: overallProgress > 50 ? 'Top 25%' : 'Building momentum',
        similarLearners: 0,
      },
      performanceMetrics: analytics?.performanceMetrics || {},
    };
  }, [learningNodes, userStats, achievements, analytics, getLearningRecommendations]);

  const timeRanges = [
    { value: '7d', label: '7 Days' },
    { value: '30d', label: '30 Days' },
    { value: '90d', label: '3 Months' },
    { value: '1y', label: '1 Year' },
    { value: 'all', label: 'All Time' }
  ];

  const subjects = [
    { value: 'all', label: 'All Subjects' },
    { value: 'mathematics', label: 'Mathematics' },
    { value: 'history', label: 'History' },
    { value: 'programming', label: 'Programming' },
    { value: 'science', label: 'Science' }
  ];

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <div className="container mx-auto px-4 py-8">
          <div className="animate-pulse space-y-6">
            <div className="h-8 bg-surface-100 rounded-lg w-1/3"></div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="h-32 bg-surface-100 rounded-lg"></div>
              ))}
            </div>
            <div className="h-96 bg-surface-100 rounded-lg"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-6 lg:py-8">
        {/* Header Section */}
        <div className="mb-8">
          <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 mb-6">
            <div>
              <h1 className="text-2xl lg:text-3xl font-heading font-bold text-text-primary mb-2">
                Progress Analytics Dashboard
              </h1>
              <p className="text-text-secondary font-body">
                Comprehensive insights into your learning journey with AI-powered recommendations
              </p>
            </div>
            
            <div className="flex flex-col sm:flex-row gap-3">
              <button
                onClick={() => setShowExportModal(true)}
                className="btn btn-outline px-4 py-2 text-sm"
              >
                <Icon name="Download" size={16} className="mr-2" />
                Export Progress
              </button>
              <Link
                to="/interactive-learning-session"
                className="btn btn-primary px-4 py-2 text-sm"
              >
                <Icon name="Play" size={16} className="mr-2" />
                Continue Learning
              </Link>
            </div>
          </div>

          {/* Filters */}
          <div className="flex flex-col sm:flex-row gap-4 p-4 bg-surface border border-border rounded-lg">
            <div className="flex-1">
              <label className="block text-sm font-medium text-text-secondary mb-2">
                Time Range
              </label>
              <select
                value={selectedTimeRange}
                onChange={(e) => setSelectedTimeRange(e.target.value)}
                className="w-full input text-sm"
              >
                {timeRanges.map(range => (
                  <option key={range.value} value={range.value}>
                    {range.label}
                  </option>
                ))}
              </select>
            </div>
            
            <div className="flex-1">
              <label className="block text-sm font-medium text-text-secondary mb-2">
                Subject Filter
              </label>
              <select
                value={selectedSubject}
                onChange={(e) => setSelectedSubject(e.target.value)}
                className="w-full input text-sm"
              >
                {subjects.map(subject => (
                  <option key={subject.value} value={subject.value}>
                    {subject.label}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Main Content Grid */}
        <div className="space-y-8">
          {/* Learning Metrics Overview */}
          <LearningMetricsOverview 
            data={analyticsData}
            timeRange={selectedTimeRange}
          />

          {/* Knowledge Network and Performance Charts */}
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
            <KnowledgeNetworkMap 
              subjects={analyticsData.subjects}
              conceptsMastered={analyticsData.conceptsMastered}
            />
            <PerformanceTrendChart 
              weeklyData={analyticsData.weeklyActivity}
              timeRange={selectedTimeRange}
              performanceMetrics={analyticsData.performanceMetrics}
            />
          </div>

          {/* AI Insights and Achievements */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2">
              <AIInsightsPanel insights={analyticsData.aiInsights} />
            </div>
            <div>
              <AchievementGallery achievements={analyticsData.achievements} />
            </div>
          </div>

          {/* Accessibility Analytics and Peer Comparison */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <AccessibilityAnalytics />
            <PeerComparisonCard comparison={analyticsData.peerComparison} />
          </div>

          {/* Quick Navigation */}
          <div className="bg-gradient-to-r from-primary-50 to-secondary-50 rounded-xl p-6 border border-primary-100">
            <h3 className="text-lg font-heading font-semibold text-text-primary mb-4">
              Continue Your Learning Journey
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <Link
                to="/adaptive-learning-dashboard"
                className="flex items-center space-x-3 p-4 bg-surface rounded-lg hover:shadow-warm-md transition-all duration-200 group"
              >
                <div className="w-10 h-10 bg-primary-100 rounded-lg flex items-center justify-center group-hover:bg-primary-200 transition-colors duration-200">
                  <Icon name="Brain" size={20} className="text-primary" />
                </div>
                <div>
                  <p className="font-medium text-text-primary">Dashboard</p>
                  <p className="text-sm text-text-secondary">Adaptive learning</p>
                </div>
              </Link>

              <Link
                to="/interactive-learning-session"
                className="flex items-center space-x-3 p-4 bg-surface rounded-lg hover:shadow-warm-md transition-all duration-200 group"
              >
                <div className="w-10 h-10 bg-secondary-100 rounded-lg flex items-center justify-center group-hover:bg-secondary-200 transition-colors duration-200">
                  <Icon name="Play" size={20} className="text-secondary" />
                </div>
                <div>
                  <p className="font-medium text-text-primary">Learn Now</p>
                  <p className="text-sm text-text-secondary">Interactive session</p>
                </div>
              </Link>

              <Link
                to="/user-profile-settings"
                className="flex items-center space-x-3 p-4 bg-surface rounded-lg hover:shadow-warm-md transition-all duration-200 group"
              >
                <div className="w-10 h-10 bg-accent-100 rounded-lg flex items-center justify-center group-hover:bg-accent-200 transition-colors duration-200">
                  <Icon name="Settings" size={20} className="text-accent" />
                </div>
                <div>
                  <p className="font-medium text-text-primary">Settings</p>
                  <p className="text-sm text-text-secondary">Customize profile</p>
                </div>
              </Link>
            </div>
          </div>
        </div>
      </div>

      {/* Export Modal */}
      {showExportModal && (
        <ExportProgressModal
          isOpen={showExportModal}
          onClose={() => setShowExportModal(false)}
          analyticsData={analyticsData}
        />
      )}
    </div>
  );
};

export default ProgressAnalyticsDashboard;