import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const PeerComparisonCard = ({ comparison }) => {
  const [showDetails, setShowDetails] = useState(false);

  // Mock detailed peer data
  const detailedComparison = {
    categories: [
      {
        name: 'Learning Hours',
        userValue: 156,
        peerAverage: 120,
        percentile: 85,
        trend: 'up',
        unit: 'hours'
      },
      {
        name: 'Concepts Mastered',
        userValue: 47,
        peerAverage: 35,
        percentile: 78,
        trend: 'up',
        unit: 'concepts'
      },
      {
        name: 'Session Completion',
        userValue: 92,
        peerAverage: 78,
        percentile: 88,
        trend: 'up',
        unit: '%'
      },
      {
        name: 'Streak Consistency',
        userValue: 12,
        peerAverage: 8,
        percentile: 72,
        trend: 'up',
        unit: 'days'
      }
    ],
    subjectRankings: [
      { subject: 'Programming', rank: 12, total: 1247, percentile: 99 },
      { subject: 'Mathematics', rank: 45, total: 1247, percentile: 96 },
      { subject: 'History', rank: 187, total: 1247, percentile: 85 },
      { subject: 'Science', rank: 312, total: 1247, percentile: 75 }
    ],
    collaborativeMetrics: {
      groupSessions: 15,
      peerAverage: 8,
      helpfulnessRating: 4.7,
      knowledgeSharing: 23
    }
  };

  const getPercentileColor = (percentile) => {
    if (percentile >= 90) return 'success';
    if (percentile >= 75) return 'primary';
    if (percentile >= 50) return 'accent';
    return 'secondary';
  };

  const getTrendIcon = (trend) => {
    return trend === 'up' ? 'TrendingUp' : trend === 'down' ? 'TrendingDown' : 'Minus';
  };

  const getTrendColor = (trend) => {
    return trend === 'up' ? 'success' : trend === 'down' ? 'error' : 'text-secondary';
  };

  return (
    <div className="card p-6">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-secondary-100 rounded-lg flex items-center justify-center">
            <Icon name="Users" size={20} className="text-secondary" />
          </div>
          <div>
            <h3 className="text-lg font-heading font-semibold text-text-primary">
              Peer Comparison
            </h3>
            <p className="text-sm text-text-secondary font-caption">
              Compare with {comparison?.similarLearners?.toLocaleString()} similar learners
            </p>
          </div>
        </div>

        <button
          onClick={() => setShowDetails(!showDetails)}
          className="text-sm text-secondary hover:text-secondary-700 font-medium transition-colors duration-200"
        >
          {showDetails ? 'Show Less' : 'Show Details'}
        </button>
      </div>

      {/* Overall Ranking */}
      <div className="mb-6 p-4 bg-gradient-to-r from-secondary-50 to-primary-50 rounded-lg">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm text-text-secondary mb-1">Overall Ranking</p>
            <p className="text-2xl font-heading font-bold text-text-primary">
              {comparison?.ranking}
            </p>
            <p className="text-sm text-text-secondary">
              of all learners
            </p>
          </div>
          <div className="text-right">
            <div className="w-16 h-16 bg-secondary rounded-full flex items-center justify-center">
              <Icon name="Trophy" size={24} color="white" />
            </div>
          </div>
        </div>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-3 gap-4 mb-6">
        <div className="text-center p-3 bg-surface-50 rounded-lg">
          <p className="text-lg font-heading font-semibold text-text-primary">
            {comparison?.averageProgress}%
          </p>
          <p className="text-xs text-text-secondary">Avg Progress</p>
          <div className="flex items-center justify-center mt-1">
            <Icon name="TrendingUp" size={12} className="text-success mr-1" />
            <span className="text-xs text-success">+8%</span>
          </div>
        </div>

        <div className="text-center p-3 bg-surface-50 rounded-lg">
          <p className="text-lg font-heading font-semibold text-text-primary">
            {comparison?.averageHours}h
          </p>
          <p className="text-xs text-text-secondary">Avg Hours</p>
          <div className="flex items-center justify-center mt-1">
            <Icon name="TrendingUp" size={12} className="text-success mr-1" />
            <span className="text-xs text-success">+36h</span>
          </div>
        </div>

        <div className="text-center p-3 bg-surface-50 rounded-lg">
          <p className="text-lg font-heading font-semibold text-text-primary">
            {comparison?.averageStreak}
          </p>
          <p className="text-xs text-text-secondary">Avg Streak</p>
          <div className="flex items-center justify-center mt-1">
            <Icon name="TrendingUp" size={12} className="text-success mr-1" />
            <span className="text-xs text-success">+4 days</span>
          </div>
        </div>
      </div>

      {/* Detailed Comparison */}
      {showDetails && (
        <div className="space-y-6 animate-fade-in">
          {/* Category Breakdown */}
          <div>
            <h4 className="text-sm font-medium text-text-primary mb-4">
              Performance Categories
            </h4>
            <div className="space-y-3">
              {detailedComparison.categories.map((category, index) => (
                <div key={index} className="p-3 bg-surface-50 rounded-lg">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium text-text-primary">
                      {category.name}
                    </span>
                    <div className="flex items-center space-x-2">
                      <Icon 
                        name={getTrendIcon(category.trend)} 
                        size={14} 
                        className={`text-${getTrendColor(category.trend)}`}
                      />
                      <span className={`text-sm font-medium text-${getPercentileColor(category.percentile)}`}>
                        {category.percentile}th percentile
                      </span>
                    </div>
                  </div>
                  
                  <div className="flex items-center justify-between text-sm text-text-secondary mb-2">
                    <span>You: {category.userValue}{category.unit}</span>
                    <span>Avg: {category.peerAverage}{category.unit}</span>
                  </div>
                  
                  <div className="w-full bg-surface-100 rounded-full h-2">
                    <div 
                      className={`bg-${getPercentileColor(category.percentile)} h-2 rounded-full transition-all duration-500`}
                      style={{ width: `${category.percentile}%` }}
                    ></div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Subject Rankings */}
          <div>
            <h4 className="text-sm font-medium text-text-primary mb-4">
              Subject Rankings
            </h4>
            <div className="space-y-2">
              {detailedComparison.subjectRankings.map((subject, index) => (
                <div key={index} className="flex items-center justify-between p-3 bg-surface-50 rounded-lg">
                  <div className="flex items-center space-x-3">
                    <div className={`w-8 h-8 bg-${getPercentileColor(subject.percentile)}-100 rounded-lg flex items-center justify-center`}>
                      <span className="text-sm font-bold text-text-primary">
                        #{subject.rank}
                      </span>
                    </div>
                    <div>
                      <p className="text-sm font-medium text-text-primary">
                        {subject.subject}
                      </p>
                      <p className="text-xs text-text-secondary">
                        of {subject.total.toLocaleString()} learners
                      </p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className={`text-sm font-medium text-${getPercentileColor(subject.percentile)}`}>
                      {subject.percentile}th
                    </p>
                    <p className="text-xs text-text-secondary">percentile</p>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Collaborative Metrics */}
          <div className="p-4 bg-gradient-to-r from-primary-50 to-secondary-50 rounded-lg">
            <h4 className="text-sm font-medium text-text-primary mb-3">
              Collaborative Learning
            </h4>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-lg font-heading font-semibold text-primary">
                  {detailedComparison.collaborativeMetrics.groupSessions}
                </p>
                <p className="text-xs text-text-secondary">Group Sessions</p>
                <p className="text-xs text-success">
                  +{detailedComparison.collaborativeMetrics.groupSessions - detailedComparison.collaborativeMetrics.peerAverage} vs avg
                </p>
              </div>
              <div>
                <p className="text-lg font-heading font-semibold text-secondary">
                  {detailedComparison.collaborativeMetrics.helpfulnessRating}/5
                </p>
                <p className="text-xs text-text-secondary">Helpfulness Rating</p>
                <p className="text-xs text-success">Above average</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Privacy Notice */}
      <div className="mt-4 p-3 bg-surface-50 rounded-lg">
        <div className="flex items-start space-x-2">
          <Icon name="Shield" size={14} className="text-text-secondary flex-shrink-0 mt-0.5" />
          <p className="text-xs text-text-secondary">
            All comparisons are anonymized and aggregated. Individual learner data remains private and secure.
          </p>
        </div>
      </div>
    </div>
  );
};

export default PeerComparisonCard;