import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const ExportProgressModal = ({ isOpen, onClose, analyticsData }) => {
  const [exportFormat, setExportFormat] = useState('pdf');
  const [exportScope, setExportScope] = useState('complete');
  const [includePersonalData, setIncludePersonalData] = useState(true);
  const [isExporting, setIsExporting] = useState(false);

  const exportFormats = [
    { value: 'pdf', label: 'PDF Report', icon: 'FileText', description: 'Comprehensive visual report' },
    { value: 'csv', label: 'CSV Data', icon: 'Database', description: 'Raw data for analysis' },
    { value: 'json', label: 'JSON Export', icon: 'Code', description: 'Structured data format' },
    { value: 'image', label: 'Image Summary', icon: 'Image', description: 'Visual progress snapshot' }
  ];

  const exportScopes = [
    { value: 'complete', label: 'Complete Analytics', description: 'All available data and insights' },
    { value: 'summary', label: 'Progress Summary', description: 'Key metrics and achievements only' },
    { value: 'performance', label: 'Performance Data', description: 'Learning trends and statistics' },
    { value: 'achievements', label: 'Achievements Only', description: 'Badges and milestones earned' }
  ];

  const handleExport = async () => {
    setIsExporting(true);
    
    // Simulate export process
    await new Promise(resolve => setTimeout(resolve, 2000));
    
    // Mock export logic
    const exportData = {
      format: exportFormat,
      scope: exportScope,
      includePersonalData,
      timestamp: new Date().toISOString(),
      data: analyticsData
    };

    console.log('Exporting data:', exportData);
    
    // In a real implementation, this would trigger the actual export
    // For now, we'll just show a success message
    setIsExporting(false);
    onClose();
    
    // Show success notification (in a real app, you'd use a toast/notification system)
    alert(`Progress report exported successfully as ${exportFormat.toUpperCase()}!`);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-max bg-black bg-opacity-50 flex items-center justify-center p-4">
      <div className="bg-surface rounded-xl shadow-warm-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-border">
          <div>
            <h2 className="text-xl font-heading font-semibold text-text-primary">
              Export Progress Report
            </h2>
            <p className="text-sm text-text-secondary font-caption mt-1">
              Download your learning analytics and progress data
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-surface-50 rounded-lg transition-colors duration-200"
          >
            <Icon name="X" size={20} className="text-text-secondary" />
          </button>
        </div>

        <div className="p-6 space-y-6">
          {/* Export Format Selection */}
          <div>
            <h3 className="text-sm font-medium text-text-primary mb-3">
              Export Format
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {exportFormats.map((format) => (
                <button
                  key={format.value}
                  onClick={() => setExportFormat(format.value)}
                  className={`p-4 rounded-lg border-2 text-left transition-all duration-200 ${
                    exportFormat === format.value
                      ? 'border-primary bg-primary-50' :'border-border hover:border-border-dark bg-surface-50'
                  }`}
                >
                  <div className="flex items-start space-x-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${
                      exportFormat === format.value
                        ? 'bg-primary text-white' :'bg-surface text-text-secondary'
                    }`}>
                      <Icon name={format.icon} size={16} />
                    </div>
                    <div>
                      <p className="font-medium text-text-primary">
                        {format.label}
                      </p>
                      <p className="text-sm text-text-secondary">
                        {format.description}
                      </p>
                    </div>
                  </div>
                </button>
              ))}
            </div>
          </div>

          {/* Export Scope */}
          <div>
            <h3 className="text-sm font-medium text-text-primary mb-3">
              Data Scope
            </h3>
            <div className="space-y-2">
              {exportScopes.map((scope) => (
                <button
                  key={scope.value}
                  onClick={() => setExportScope(scope.value)}
                  className={`w-full p-3 rounded-lg border text-left transition-all duration-200 ${
                    exportScope === scope.value
                      ? 'border-primary bg-primary-50' :'border-border hover:border-border-dark'
                  }`}
                >
                  <div className="flex items-center space-x-3">
                    <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${
                      exportScope === scope.value
                        ? 'border-primary bg-primary' :'border-border'
                    }`}>
                      {exportScope === scope.value && (
                        <div className="w-2 h-2 bg-white rounded-full"></div>
                      )}
                    </div>
                    <div>
                      <p className="font-medium text-text-primary">
                        {scope.label}
                      </p>
                      <p className="text-sm text-text-secondary">
                        {scope.description}
                      </p>
                    </div>
                  </div>
                </button>
              ))}
            </div>
          </div>

          {/* Privacy Options */}
          <div>
            <h3 className="text-sm font-medium text-text-primary mb-3">
              Privacy Settings
            </h3>
            <div className="space-y-3">
              <label className="flex items-start space-x-3 cursor-pointer">
                <div className="relative">
                  <input
                    type="checkbox"
                    checked={includePersonalData}
                    onChange={(e) => setIncludePersonalData(e.target.checked)}
                    className="sr-only"
                  />
                  <div className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all duration-200 ${
                    includePersonalData
                      ? 'border-primary bg-primary' :'border-border'
                  }`}>
                    {includePersonalData && (
                      <Icon name="Check" size={12} color="white" />
                    )}
                  </div>
                </div>
                <div>
                  <p className="font-medium text-text-primary">
                    Include Personal Information
                  </p>
                  <p className="text-sm text-text-secondary">
                    Include name, email, and profile details in the export
                  </p>
                </div>
              </label>

              <div className="p-3 bg-accent-50 rounded-lg">
                <div className="flex items-start space-x-2">
                  <Icon name="Shield" size={16} className="text-accent flex-shrink-0 mt-0.5" />
                  <div>
                    <p className="text-sm font-medium text-text-primary">
                      Data Privacy Notice
                    </p>
                    <p className="text-sm text-text-secondary mt-1">
                      Exported data is for personal use only. Sharing learning analytics 
                      with third parties should comply with privacy regulations.
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Export Preview */}
          <div className="p-4 bg-surface-50 rounded-lg">
            <h4 className="text-sm font-medium text-text-primary mb-3">
              Export Preview
            </h4>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-text-secondary">Format:</span>
                <span className="text-text-primary font-medium">
                  {exportFormats.find(f => f.value === exportFormat)?.label}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-text-secondary">Scope:</span>
                <span className="text-text-primary font-medium">
                  {exportScopes.find(s => s.value === exportScope)?.label}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-text-secondary">Personal Data:</span>
                <span className="text-text-primary font-medium">
                  {includePersonalData ? 'Included' : 'Excluded'}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-text-secondary">File Size (est.):</span>
                <span className="text-text-primary font-medium">
                  {exportFormat === 'pdf' ? '2.5 MB' : 
                   exportFormat === 'csv' ? '150 KB' :
                   exportFormat === 'json' ? '85 KB' : '1.2 MB'}
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between p-6 border-t border-border">
          <button
            onClick={onClose}
            className="btn btn-outline px-4 py-2 text-sm"
          >
            Cancel
          </button>
          
          <button
            onClick={handleExport}
            disabled={isExporting}
            className="btn btn-primary px-6 py-2 text-sm disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isExporting ? (
              <div className="flex items-center space-x-2">
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                <span>Exporting...</span>
              </div>
            ) : (
              <div className="flex items-center space-x-2">
                <Icon name="Download" size={16} />
                <span>Export Report</span>
              </div>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ExportProgressModal;