import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const AIInsightsPanel = ({ insights }) => {
  const [expandedInsight, setExpandedInsight] = useState(null);

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'high': return 'error';
      case 'medium': return 'accent';
      case 'low': return 'success';
      default: return 'primary';
    }
  };

  const getPriorityIcon = (priority) => {
    switch (priority) {
      case 'high': return 'AlertTriangle';
      case 'medium': return 'Clock';
      case 'low': return 'Info';
      default: return 'Lightbulb';
    }
  };

  const getTypeIcon = (type) => {
    switch (type) {
      case 'recommendation': return 'Lightbulb';
      case 'gap-analysis': return 'Target';
      case 'prediction': return 'TrendingUp';
      default: return 'Brain';
    }
  };

  const getConfidenceScore = (insight) => {
    const priorityScores = { high: 92, medium: 85, low: 78 };
    return priorityScores[insight.priority] || 82;
  };

  const getTypeColor = (type) => {
    switch (type) {
      case 'recommendation': return 'primary';
      case 'gap-analysis': return 'accent';
      case 'prediction': return 'secondary';
      default: return 'primary';
    }
  };

  const handleInsightAction = (insight) => {
    console.log('Taking action for insight:', insight.action);
    // Implement insight action logic
  };

  return (
    <div className="card p-6">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-gradient-to-br from-primary to-secondary rounded-lg flex items-center justify-center">
            <Icon name="Brain" size={20} color="white" />
          </div>
          <div>
            <h3 className="text-lg font-heading font-semibold text-text-primary">
              AI Learning Insights
            </h3>
            <p className="text-sm text-text-secondary font-caption">
              Personalized recommendations based on your learning patterns
            </p>
          </div>
        </div>
        
        <div className="flex items-center space-x-2">
          <div className="w-2 h-2 bg-primary rounded-full animate-pulse"></div>
          <span className="text-xs text-text-secondary font-caption">Live Analysis</span>
        </div>
      </div>

      <div className="space-y-4">
        {insights?.map((insight, index) => (
          <div
            key={index}
            className={`border-2 rounded-lg transition-all duration-200 ${
              expandedInsight === index
                ? `border-${getTypeColor(insight.type)}-200 bg-${getTypeColor(insight.type)}-50`
                : 'border-border bg-surface hover:border-border-dark'
            }`}
          >
            {/* Insight Header */}
            <div 
              className="p-4 cursor-pointer"
              onClick={() => setExpandedInsight(expandedInsight === index ? null : index)}
            >
              <div className="flex items-start space-x-3">
                <div className={`w-8 h-8 bg-${getTypeColor(insight.type)}-100 rounded-lg flex items-center justify-center flex-shrink-0`}>
                  <Icon 
                    name={getTypeIcon(insight.type)} 
                    size={16} 
                    className={`text-${getTypeColor(insight.type)}`}
                  />
                </div>
                
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between mb-2">
                    <h4 className="font-medium text-text-primary">
                      {insight.title}
                    </h4>
                    <div className="flex items-center space-x-2">
                      <div className={`flex items-center space-x-1 px-2 py-1 rounded-full bg-${getPriorityColor(insight.priority)}-100`}>
                        <Icon 
                          name={getPriorityIcon(insight.priority)} 
                          size={12} 
                          className={`text-${getPriorityColor(insight.priority)}`}
                        />
                        <span className={`text-xs font-medium text-${getPriorityColor(insight.priority)} capitalize`}>
                          {insight.priority}
                        </span>
                      </div>
                      <Icon 
                        name={expandedInsight === index ? "ChevronUp" : "ChevronDown"} 
                        size={16} 
                        className="text-text-secondary"
                      />
                    </div>
                  </div>
                  
                  <p className="text-sm text-text-secondary line-clamp-2">
                    {insight.content}
                  </p>
                </div>
              </div>
            </div>

            {/* Expanded Content */}
            {expandedInsight === index && (
              <div className="px-4 pb-4 border-t border-border-light">
                <div className="pt-4">
                  <div className="bg-surface rounded-lg p-4 mb-4">
                    <h5 className="text-sm font-medium text-text-primary mb-2">
                      Detailed Analysis
                    </h5>
                    <p className="text-sm text-text-secondary leading-relaxed">
                      {insight.content}
                    </p>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex flex-col sm:flex-row gap-3">
                    <button
                      onClick={() => handleInsightAction(insight)}
                      className={`btn bg-${getTypeColor(insight.type)} text-white hover:bg-${getTypeColor(insight.type)}-700 px-4 py-2 text-sm flex-1`}
                    >
                      <Icon name="ArrowRight" size={14} className="mr-2" />
                      {insight.action}
                    </button>
                    
                    <div className="flex space-x-2">
                      <button className="btn btn-outline px-3 py-2 text-sm">
                        <Icon name="BookOpen" size={14} className="mr-1" />
                        Learn More
                      </button>
                      <button className="btn btn-outline px-3 py-2 text-sm">
                        <Icon name="X" size={14} className="mr-1" />
                        Dismiss
                      </button>
                    </div>
                  </div>

                  {/* Confidence Score */}
                  <div className="mt-4 pt-3 border-t border-border-light">
                    <div className="flex items-center justify-between text-xs">
                      <span className="text-text-secondary">AI Confidence</span>
                      <span className="font-medium text-text-primary">
                        {getConfidenceScore(insight)}%
                      </span>
                    </div>
                    <div className="w-full bg-surface-100 rounded-full h-1.5 mt-1">
                      <div 
                        className={`bg-${getTypeColor(insight.type)} h-1.5 rounded-full transition-all duration-500`}
                        style={{ width: `${getConfidenceScore(insight)}%` }}
                      ></div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* AI Learning Stats */}
      <div className="mt-6 pt-4 border-t border-border">
        <div className="grid grid-cols-3 gap-4 text-center">
          <div className="p-3 bg-primary-50 rounded-lg">
            <p className="text-lg font-heading font-semibold text-primary">
              {insights?.filter(i => i.type === 'recommendation').length || 0}
            </p>
            <p className="text-xs text-text-secondary">Recommendations</p>
          </div>
          <div className="p-3 bg-accent-50 rounded-lg">
            <p className="text-lg font-heading font-semibold text-accent">
              {insights?.filter(i => i.type === 'gap-analysis').length || 0}
            </p>
            <p className="text-xs text-text-secondary">Gap Analysis</p>
          </div>
          <div className="p-3 bg-secondary-50 rounded-lg">
            <p className="text-lg font-heading font-semibold text-secondary">
              {insights?.filter(i => i.type === 'prediction').length || 0}
            </p>
            <p className="text-xs text-text-secondary">Predictions</p>
          </div>
        </div>
      </div>

      {/* AI Attribution */}
      <div className="mt-4 p-3 bg-gradient-to-r from-primary-50 to-secondary-50 rounded-lg">
        <div className="flex items-center space-x-2 text-xs text-text-secondary">
          <Icon name="Sparkles" size={14} className="text-primary" />
          <span>
            Insights generated using advanced machine learning algorithms analyzing your learning patterns, 
            performance data, and behavioral indicators.
          </span>
        </div>
      </div>
    </div>
  );
};

export default AIInsightsPanel;