import React, { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';
import Icon from 'components/AppIcon';

const PerformanceTrendChart = ({ weeklyData, timeRange, performanceMetrics = {} }) => {
  const [chartType, setChartType] = useState('line');
  const [selectedMetric, setSelectedMetric] = useState('hours');

  const accuracy = performanceMetrics.accuracy ?? 0;
  const engagement = performanceMetrics.engagement ?? 0;

  const getChartData = () => {
    const base =
      weeklyData?.map((item) => ({
        ...item,
        accuracy,
        engagement,
      })) || [];

    if (timeRange === '30d') {
      return Array.from({ length: 30 }, (_, i) => ({
        day: `Day ${i + 1}`,
        hours: base[i % Math.max(base.length, 1)]?.hours || 0,
        concepts: base[i % Math.max(base.length, 1)]?.concepts || 0,
        accuracy,
        engagement,
      }));
    }

    if (timeRange === '90d') {
      const avgHours =
        base.reduce((sum, entry) => sum + (entry.hours || 0), 0) / Math.max(base.length, 1);
      const avgConcepts =
        base.reduce((sum, entry) => sum + (entry.concepts || 0), 0) / Math.max(base.length, 1);
      return Array.from({ length: 12 }, (_, i) => ({
        day: `Week ${i + 1}`,
        hours: Math.round(avgHours * (i + 1) * 0.15 * 10) / 10,
        concepts: Math.round(avgConcepts * (i + 1) * 0.12),
        accuracy,
        engagement,
      }));
    }

    return base;
  };

  const chartData = getChartData();

  const metrics = [
    { key: 'hours', label: 'Learning Hours', color: '#4F46E5', unit: 'h' },
    { key: 'concepts', label: 'Concepts Learned', color: '#06B6D4', unit: '' },
    { key: 'accuracy', label: 'Accuracy Rate', color: '#10B981', unit: '%' },
    { key: 'engagement', label: 'Engagement Score', color: '#F59E0B', unit: '%' }
  ];

  const selectedMetricData = metrics.find(m => m.key === selectedMetric);

  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-surface border border-border rounded-lg p-3 shadow-warm-md">
          <p className="text-sm font-medium text-text-primary mb-2">{label}</p>
          {payload.map((entry, index) => (
            <div key={index} className="flex items-center space-x-2 text-sm">
              <div 
                className="w-3 h-3 rounded-full"
                style={{ backgroundColor: entry.color }}
              ></div>
              <span className="text-text-secondary">{entry.name}:</span>
              <span className="font-medium text-text-primary">
                {typeof entry.value === 'number' ? entry.value.toFixed(1) : entry.value}
                {selectedMetricData?.unit}
              </span>
            </div>
          ))}
        </div>
      );
    }
    return null;
  };

  const renderChart = () => {
    const commonProps = {
      data: chartData,
      margin: { top: 5, right: 30, left: 20, bottom: 5 }
    };

    if (chartType === 'area') {
      return (
        <ResponsiveContainer width="100%" height={250}>
          <AreaChart {...commonProps}>
            <CartesianGrid strokeDasharray="3 3" stroke="#E5E7EB" />
            <XAxis 
              dataKey="day" 
              stroke="#6B7280"
              fontSize={12}
            />
            <YAxis 
              stroke="#6B7280"
              fontSize={12}
            />
            <Tooltip content={<CustomTooltip />} />
            <Area
              type="monotone"
              dataKey={selectedMetric}
              stroke={selectedMetricData?.color}
              fill={selectedMetricData?.color}
              fillOpacity={0.3}
              strokeWidth={2}
              name={selectedMetricData?.label}
            />
          </AreaChart>
        </ResponsiveContainer>
      );
    }

    return (
      <ResponsiveContainer width="100%" height={250}>
        <LineChart {...commonProps}>
          <CartesianGrid strokeDasharray="3 3" stroke="#E5E7EB" />
          <XAxis 
            dataKey="day" 
            stroke="#6B7280"
            fontSize={12}
          />
          <YAxis 
            stroke="#6B7280"
            fontSize={12}
          />
          <Tooltip content={<CustomTooltip />} />
          <Line
            type="monotone"
            dataKey={selectedMetric}
            stroke={selectedMetricData?.color}
            strokeWidth={3}
            dot={{ fill: selectedMetricData?.color, strokeWidth: 2, r: 4 }}
            activeDot={{ r: 6, stroke: selectedMetricData?.color, strokeWidth: 2 }}
            name={selectedMetricData?.label}
          />
        </LineChart>
      </ResponsiveContainer>
    );
  };

  return (
    <div className="card p-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
        <h3 className="text-lg font-heading font-semibold text-text-primary">
          Performance Trends
        </h3>
        
        <div className="flex items-center space-x-3">
          {/* Chart Type Toggle */}
          <div className="flex bg-surface-50 rounded-lg p-1">
            <button
              onClick={() => setChartType('line')}
              className={`px-3 py-1 rounded text-sm font-medium transition-all duration-200 ${
                chartType === 'line' ?'bg-primary text-white shadow-sm' :'text-text-secondary hover:text-text-primary'
              }`}
            >
              <Icon name="TrendingUp" size={14} className="mr-1" />
              Line
            </button>
            <button
              onClick={() => setChartType('area')}
              className={`px-3 py-1 rounded text-sm font-medium transition-all duration-200 ${
                chartType === 'area' ?'bg-primary text-white shadow-sm' :'text-text-secondary hover:text-text-primary'
              }`}
            >
              <Icon name="BarChart3" size={14} className="mr-1" />
              Area
            </button>
          </div>
        </div>
      </div>

      {/* Metric Selector */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-6">
        {metrics.map((metric) => (
          <button
            key={metric.key}
            onClick={() => setSelectedMetric(metric.key)}
            className={`p-3 rounded-lg text-left transition-all duration-200 ${
              selectedMetric === metric.key
                ? 'bg-primary-50 border-2 border-primary' :'bg-surface-50 border-2 border-transparent hover:bg-surface-100'
            }`}
          >
            <div className="flex items-center space-x-2 mb-1">
              <div 
                className="w-3 h-3 rounded-full"
                style={{ backgroundColor: metric.color }}
              ></div>
              <span className="text-xs font-medium text-text-primary">
                {metric.label}
              </span>
            </div>
            <div className="text-lg font-heading font-semibold text-text-primary">
              {chartData.length > 0 && (
                <>
                  {typeof chartData[chartData.length - 1][metric.key] === 'number' 
                    ? chartData[chartData.length - 1][metric.key].toFixed(1)
                    : chartData[chartData.length - 1][metric.key]
                  }
                  <span className="text-sm text-text-secondary ml-1">
                    {metric.unit}
                  </span>
                </>
              )}
            </div>
          </button>
        ))}
      </div>

      {/* Chart */}
      <div className="bg-surface-50 rounded-lg p-4">
        {renderChart()}
      </div>

      {/* Insights */}
      <div className="mt-4 p-4 bg-gradient-to-r from-primary-50 to-secondary-50 rounded-lg">
        <div className="flex items-start space-x-3">
          <div className="w-8 h-8 bg-primary-100 rounded-lg flex items-center justify-center flex-shrink-0">
            <Icon name="Lightbulb" size={16} className="text-primary" />
          </div>
          <div>
            <h4 className="text-sm font-medium text-text-primary mb-1">
              Performance Insight
            </h4>
            <p className="text-sm text-text-secondary">
              {selectedMetric === 'hours' && "Your learning hours show consistent growth. Peak performance occurs mid-week."}
              {selectedMetric === 'concepts' && "Concept acquisition rate is accelerating. You're building strong knowledge foundations."}
              {selectedMetric === 'accuracy' && "Accuracy trends indicate improving understanding. Focus areas are showing progress."}
              {selectedMetric === 'engagement' && "Engagement levels remain high. Interactive content drives better retention."}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PerformanceTrendChart;