import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const AchievementGallery = ({ achievements }) => {
  const [selectedCategory, setSelectedCategory] = useState('all');

  const categories = [
    { value: 'all', label: 'All', count: achievements?.length || 0 },
    { value: 'earned', label: 'Earned', count: achievements?.filter(a => a.earned).length || 0 },
    { value: 'progress', label: 'In Progress', count: achievements?.filter(a => !a.earned && a.progress).length || 0 }
  ];

  const filteredAchievements = achievements?.filter(achievement => {
    if (selectedCategory === 'all') return true;
    if (selectedCategory === 'earned') return achievement.earned;
    if (selectedCategory === 'progress') return !achievement.earned && achievement.progress;
    return true;
  }) || [];

  const getAchievementColor = (achievement) => {
    if (achievement.earned) return 'success';
    if (achievement.progress && achievement.progress > 0) return 'accent';
    return 'surface-200';
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric'
    });
  };

  return (
    <div className="card p-6">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-heading font-semibold text-text-primary">
          Achievement Gallery
        </h3>
        <div className="flex items-center space-x-1 text-sm text-text-secondary">
          <Icon name="Award" size={16} />
          <span>{achievements?.filter(a => a.earned).length || 0} earned</span>
        </div>
      </div>

      {/* Category Filter */}
      <div className="flex space-x-1 mb-6 bg-surface-50 rounded-lg p-1">
        {categories.map((category) => (
          <button
            key={category.value}
            onClick={() => setSelectedCategory(category.value)}
            className={`flex-1 px-3 py-2 rounded text-sm font-medium transition-all duration-200 ${
              selectedCategory === category.value
                ? 'bg-primary text-white shadow-sm'
                : 'text-text-secondary hover:text-text-primary'
            }`}
          >
            {category.label}
            <span className="ml-1 text-xs opacity-75">({category.count})</span>
          </button>
        ))}
      </div>

      {/* Achievement Grid */}
      <div className="space-y-3 max-h-80 overflow-y-auto">
        {filteredAchievements.map((achievement) => (
          <div
            key={achievement.id}
            className={`p-4 rounded-lg border-2 transition-all duration-200 hover:shadow-warm-sm ${
              achievement.earned
                ? 'bg-success-50 border-success-200'
                : achievement.progress
                ? 'bg-accent-50 border-accent-200' :'bg-surface-50 border-surface-200'
            }`}
          >
            <div className="flex items-start space-x-3">
              {/* Achievement Icon */}
              <div className={`w-12 h-12 rounded-lg flex items-center justify-center flex-shrink-0 ${
                achievement.earned
                  ? 'bg-success text-white'
                  : achievement.progress
                  ? 'bg-accent text-white' :'bg-surface-200 text-text-secondary'
              }`}>
                <Icon 
                  name={achievement.icon} 
                  size={20}
                />
              </div>

              {/* Achievement Details */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between mb-1">
                  <h4 className="font-medium text-text-primary truncate">
                    {achievement.title}
                  </h4>
                  {achievement.earned && (
                    <span className="text-xs text-success font-medium bg-success-100 px-2 py-1 rounded-full">
                      {formatDate(achievement.date)}
                    </span>
                  )}
                </div>
                
                <p className="text-sm text-text-secondary mb-2 line-clamp-2">
                  {achievement.description}
                </p>

                {/* Progress Bar for In-Progress Achievements */}
                {!achievement.earned && achievement.progress && (
                  <div className="space-y-1">
                    <div className="flex items-center justify-between text-xs">
                      <span className="text-text-secondary">Progress</span>
                      <span className="font-medium text-text-primary">
                        {achievement.progress}%
                      </span>
                    </div>
                    <div className="w-full bg-surface-100 rounded-full h-2">
                      <div 
                        className="bg-accent h-2 rounded-full transition-all duration-500 ease-out"
                        style={{ width: `${achievement.progress}%` }}
                      ></div>
                    </div>
                  </div>
                )}

                {/* Achievement Status */}
                {achievement.earned && (
                  <div className="flex items-center space-x-2 text-xs text-success">
                    <Icon name="CheckCircle" size={14} />
                    <span className="font-medium">Achievement Unlocked!</span>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Empty State */}
      {filteredAchievements.length === 0 && (
        <div className="text-center py-8">
          <div className="w-16 h-16 bg-surface-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Icon name="Award" size={24} className="text-text-secondary" />
          </div>
          <h4 className="font-medium text-text-primary mb-2">
            No achievements in this category
          </h4>
          <p className="text-sm text-text-secondary">
            Keep learning to unlock new achievements!
          </p>
        </div>
      )}

      {/* Achievement Stats */}
      <div className="mt-6 pt-4 border-t border-border">
        <div className="grid grid-cols-3 gap-4 text-center">
          <div>
            <p className="text-lg font-heading font-semibold text-text-primary">
              {achievements?.filter(a => a.earned).length || 0}
            </p>
            <p className="text-xs text-text-secondary">Earned</p>
          </div>
          <div>
            <p className="text-lg font-heading font-semibold text-text-primary">
              {achievements?.filter(a => !a.earned && a.progress).length || 0}
            </p>
            <p className="text-xs text-text-secondary">In Progress</p>
          </div>
          <div>
            <p className="text-lg font-heading font-semibold text-text-primary">
              {Math.round(((achievements?.filter(a => a.earned).length || 0) / (achievements?.length || 1)) * 100)}%
            </p>
            <p className="text-xs text-text-secondary">Completion</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AchievementGallery;