import React from 'react';
import Icon from 'components/AppIcon';

const LearningMetricsOverview = ({ data, timeRange }) => {
  const metrics = [
    {
      title: 'Overall Progress',
      value: `${data.overallProgress}%`,
      change: '+12%',
      changeType: 'positive',
      icon: 'TrendingUp',
      color: 'primary',
      description: 'Across all subjects'
    },
    {
      title: 'Learning Streak',
      value: `${data.learningStreak} days`,
      change: '+3 days',
      changeType: 'positive',
      icon: 'Flame',
      color: 'accent',
      description: 'Current streak'
    },
    {
      title: 'Total Hours',
      value: `${Number(data.totalHours).toFixed(1)}h`,
      change: '+24h',
      changeType: 'positive',
      icon: 'Clock',
      color: 'secondary',
      description: 'Learning time'
    },
    {
      title: 'Concepts Mastered',
      value: data.conceptsMastered,
      change: '+8',
      changeType: 'positive',
      icon: 'Target',
      color: 'success',
      description: 'Knowledge points'
    }
  ];

  const getTimeRangeLabel = () => {
    switch (timeRange) {
      case '7d': return 'this week';
      case '30d': return 'this month';
      case '90d': return 'this quarter';
      case '1y': return 'this year';
      default: return 'all time';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-heading font-semibold text-text-primary">
          Learning Metrics Overview
        </h2>
        <span className="text-sm text-text-secondary font-caption">
          Performance {getTimeRangeLabel()}
        </span>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {metrics.map((metric, index) => (
          <div
            key={index}
            className="card card-hover p-6 relative overflow-hidden"
          >
            {/* Background Pattern */}
            <div className={`absolute top-0 right-0 w-20 h-20 bg-${metric.color}-50 rounded-full -mr-10 -mt-10 opacity-50`}></div>
            
            <div className="relative z-10">
              <div className="flex items-center justify-between mb-4">
                <div className={`w-12 h-12 bg-${metric.color}-100 rounded-lg flex items-center justify-center`}>
                  <Icon 
                    name={metric.icon} 
                    size={24} 
                    className={`text-${metric.color}`}
                  />
                </div>
                <div className={`flex items-center space-x-1 text-sm ${
                  metric.changeType === 'positive' ? 'text-success' : 'text-error'
                }`}>
                  <Icon 
                    name={metric.changeType === 'positive' ? 'ArrowUp' : 'ArrowDown'} 
                    size={14} 
                  />
                  <span className="font-medium">{metric.change}</span>
                </div>
              </div>

              <div className="space-y-2">
                <h3 className="text-2xl font-heading font-bold text-text-primary">
                  {metric.value}
                </h3>
                <p className="text-sm font-medium text-text-primary">
                  {metric.title}
                </p>
                <p className="text-xs text-text-secondary font-caption">
                  {metric.description}
                </p>
              </div>

              {/* Progress Bar for Overall Progress */}
              {metric.title === 'Overall Progress' && (
                <div className="mt-4">
                  <div className="w-full bg-surface-100 rounded-full h-2">
                    <div 
                      className={`bg-${metric.color} h-2 rounded-full transition-all duration-1000 ease-out`}
                      style={{ width: `${data.overallProgress}%` }}
                    ></div>
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Subject Breakdown */}
      <div className="card p-6">
        <h3 className="text-lg font-heading font-semibold text-text-primary mb-4">
          Subject Progress Breakdown
        </h3>
        <div className="space-y-4">
          {data.subjects?.map((subject, index) => (
            <div key={index} className="flex items-center space-x-4">
              <div className="flex-1">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium text-text-primary">
                    {subject.name}
                  </span>
                  <div className="flex items-center space-x-4 text-xs text-text-secondary">
                    <span>{Number(subject.hours).toFixed(1)}h</span>
                    <span>{subject.concepts} concepts</span>
                    <span className="font-medium text-text-primary">
                      {subject.progress}%
                    </span>
                  </div>
                </div>
                <div className="w-full bg-surface-100 rounded-full h-2">
                  <div 
                    className={`bg-${subject.color} h-2 rounded-full transition-all duration-1000 ease-out`}
                    style={{ width: `${subject.progress}%` }}
                  ></div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default LearningMetricsOverview;