import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import Icon from 'components/AppIcon';

const KnowledgeNetworkMap = ({ subjects, conceptsMastered }) => {
  const svgRef = useRef();
  const [selectedNode, setSelectedNode] = useState(null);
  const [isInteractive, setIsInteractive] = useState(true);

  // Mock network data representing knowledge connections
  const networkData = {
    nodes: [
      // Core subjects
      { id: 'math', name: 'Mathematics', type: 'subject', mastery: 85, size: 20, color: '#4F46E5' },
      { id: 'history', name: 'History', type: 'subject', mastery: 72, size: 18, color: '#06B6D4' },
      { id: 'programming', name: 'Programming', type: 'subject', mastery: 91, size: 22, color: '#F59E0B' },
      { id: 'science', name: 'Science', type: 'subject', mastery: 65, size: 16, color: '#10B981' },
      
      // Mathematics concepts
      { id: 'algebra', name: 'Algebra', type: 'concept', mastery: 90, size: 12, color: '#4F46E5', parent: 'math' },
      { id: 'geometry', name: 'Geometry', type: 'concept', mastery: 78, size: 10, color: '#4F46E5', parent: 'math' },
      { id: 'calculus', name: 'Calculus', type: 'concept', mastery: 45, size: 8, color: '#4F46E5', parent: 'math' },
      
      // Programming concepts
      { id: 'javascript', name: 'JavaScript', type: 'concept', mastery: 95, size: 14, color: '#F59E0B', parent: 'programming' },
      { id: 'react', name: 'React', type: 'concept', mastery: 88, size: 12, color: '#F59E0B', parent: 'programming' },
      { id: 'algorithms', name: 'Algorithms', type: 'concept', mastery: 70, size: 10, color: '#F59E0B', parent: 'programming' },
      
      // History concepts
      { id: 'ancient', name: 'Ancient History', type: 'concept', mastery: 82, size: 11, color: '#06B6D4', parent: 'history' },
      { id: 'modern', name: 'Modern History', type: 'concept', mastery: 65, size: 9, color: '#06B6D4', parent: 'history' },
      
      // Science concepts
      { id: 'physics', name: 'Physics', type: 'concept', mastery: 60, size: 9, color: '#10B981', parent: 'science' },
      { id: 'chemistry', name: 'Chemistry', type: 'concept', mastery: 70, size: 10, color: '#10B981', parent: 'science' }
    ],
    links: [
      // Subject connections (interdisciplinary)
      { source: 'math', target: 'programming', strength: 0.8, type: 'interdisciplinary' },
      { source: 'math', target: 'science', strength: 0.6, type: 'interdisciplinary' },
      { source: 'programming', target: 'science', strength: 0.4, type: 'interdisciplinary' },
      
      // Concept to subject connections
      { source: 'algebra', target: 'math', strength: 1.0, type: 'hierarchy' },
      { source: 'geometry', target: 'math', strength: 1.0, type: 'hierarchy' },
      { source: 'calculus', target: 'math', strength: 1.0, type: 'hierarchy' },
      { source: 'javascript', target: 'programming', strength: 1.0, type: 'hierarchy' },
      { source: 'react', target: 'programming', strength: 1.0, type: 'hierarchy' },
      { source: 'algorithms', target: 'programming', strength: 1.0, type: 'hierarchy' },
      { source: 'ancient', target: 'history', strength: 1.0, type: 'hierarchy' },
      { source: 'modern', target: 'history', strength: 1.0, type: 'hierarchy' },
      { source: 'physics', target: 'science', strength: 1.0, type: 'hierarchy' },
      { source: 'chemistry', target: 'science', strength: 1.0, type: 'hierarchy' },
      
      // Concept interconnections
      { source: 'algebra', target: 'algorithms', strength: 0.7, type: 'conceptual' },
      { source: 'geometry', target: 'react', strength: 0.3, type: 'conceptual' },
      { source: 'calculus', target: 'physics', strength: 0.9, type: 'conceptual' }
    ]
  };

  useEffect(() => {
    if (!svgRef.current) return;

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const width = 400;
    const height = 300;
    
    svg.attr("width", width).attr("height", height);

    // Create simulation
    const simulation = d3.forceSimulation(networkData.nodes)
      .force("link", d3.forceLink(networkData.links).id(d => d.id).distance(d => {
        if (d.type === 'hierarchy') return 50;
        if (d.type === 'interdisciplinary') return 80;
        return 60;
      }))
      .force("charge", d3.forceManyBody().strength(-200))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collision", d3.forceCollide().radius(d => d.size + 5));

    // Create links
    const link = svg.append("g")
      .selectAll("line")
      .data(networkData.links)
      .enter().append("line")
      .attr("stroke", d => {
        switch (d.type) {
          case 'hierarchy': return '#E5E7EB';
          case 'interdisciplinary': return '#6366F1';
          case 'conceptual': return '#F59E0B';
          default: return '#E5E7EB';
        }
      })
      .attr("stroke-width", d => d.strength * 2)
      .attr("stroke-opacity", 0.6);

    // Create nodes
    const node = svg.append("g")
      .selectAll("circle")
      .data(networkData.nodes)
      .enter().append("circle")
      .attr("r", d => d.size)
      .attr("fill", d => d.color)
      .attr("stroke", "#fff")
      .attr("stroke-width", 2)
      .attr("opacity", d => d.mastery > 50 ? 1 : 0.5)
      .style("cursor", "pointer");

    // Add labels
    const labels = svg.append("g")
      .selectAll("text")
      .data(networkData.nodes)
      .enter().append("text")
      .text(d => d.name)
      .attr("font-size", d => d.type === 'subject' ? "12px" : "10px")
      .attr("font-weight", d => d.type === 'subject' ? "bold" : "normal")
      .attr("fill", "#374151")
      .attr("text-anchor", "middle")
      .attr("dy", d => d.size + 15)
      .style("pointer-events", "none");

    // Add interactivity
    node.on("click", (event, d) => {
      setSelectedNode(d);
    })
    .on("mouseover", (event, d) => {
      // Highlight connected nodes
      const connectedNodeIds = networkData.links
        .filter(link => link.source.id === d.id || link.target.id === d.id)
        .map(link => link.source.id === d.id ? link.target.id : link.source.id);
      
      node.attr("opacity", n => 
        n.id === d.id || connectedNodeIds.includes(n.id) ? 1 : 0.3
      );
      
      link.attr("stroke-opacity", l => 
        l.source.id === d.id || l.target.id === d.id ? 0.8 : 0.1
      );
    })
    .on("mouseout", () => {
      node.attr("opacity", d => d.mastery > 50 ? 1 : 0.5);
      link.attr("stroke-opacity", 0.6);
    });

    // Update positions on simulation tick
    simulation.on("tick", () => {
      link
        .attr("x1", d => d.source.x)
        .attr("y1", d => d.source.y)
        .attr("x2", d => d.target.x)
        .attr("y2", d => d.target.y);

      node
        .attr("cx", d => d.x)
        .attr("cy", d => d.y);

      labels
        .attr("x", d => d.x)
        .attr("y", d => d.y);
    });

    // Cleanup
    return () => {
      simulation.stop();
    };
  }, [isInteractive]);

  return (
    <div className="card p-6">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-heading font-semibold text-text-primary">
          Knowledge Network Map
        </h3>
        <button
          onClick={() => setIsInteractive(!isInteractive)}
          className="text-sm text-primary hover:text-primary-700 font-medium transition-colors duration-200"
        >
          <Icon name="RotateCcw" size={16} className="mr-1" />
          Reset View
        </button>
      </div>

      <div className="relative">
        <svg
          ref={svgRef}
          className="w-full h-80 border border-border rounded-lg bg-surface-50"
        ></svg>

        {/* Legend */}
        <div className="absolute top-4 left-4 bg-surface border border-border rounded-lg p-3 shadow-warm-sm">
          <h4 className="text-xs font-medium text-text-primary mb-2">Legend</h4>
          <div className="space-y-1 text-xs">
            <div className="flex items-center space-x-2">
              <div className="w-3 h-3 bg-primary rounded-full"></div>
              <span className="text-text-secondary">Mathematics</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-3 h-3 bg-secondary rounded-full"></div>
              <span className="text-text-secondary">History</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-3 h-3 bg-accent rounded-full"></div>
              <span className="text-text-secondary">Programming</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-3 h-3 bg-success rounded-full"></div>
              <span className="text-text-secondary">Science</span>
            </div>
          </div>
        </div>

        {/* Node Details Panel */}
        {selectedNode && (
          <div className="absolute top-4 right-4 bg-surface border border-border rounded-lg p-4 shadow-warm-md w-48">
            <div className="flex items-center justify-between mb-2">
              <h4 className="font-medium text-text-primary">{selectedNode.name}</h4>
              <button
                onClick={() => setSelectedNode(null)}
                className="text-text-secondary hover:text-text-primary"
              >
                <Icon name="X" size={14} />
              </button>
            </div>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-text-secondary">Type:</span>
                <span className="text-text-primary capitalize">{selectedNode.type}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-text-secondary">Mastery:</span>
                <span className="text-text-primary">{selectedNode.mastery}%</span>
              </div>
              <div className="w-full bg-surface-100 rounded-full h-2 mt-2">
                <div 
                  className="bg-primary h-2 rounded-full transition-all duration-300"
                  style={{ width: `${selectedNode.mastery}%` }}
                ></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="mt-4 text-xs text-text-secondary font-caption">
        <p>Interactive knowledge map showing your learning connections. Click nodes to explore details.</p>
        <p className="mt-1">Opacity indicates mastery level - brighter nodes represent stronger understanding.</p>
      </div>
    </div>
  );
};

export default KnowledgeNetworkMap;